const $=s=>document.querySelector(s),ns='http://www.w3.org/2000/svg';
const el=(tag,attrs={},text)=>{const n=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n;};
let selectedJSON='{}';
try{
 const [db,map]=await Promise.all(['assets/data.json','assets/rincon-map.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('Dataset unavailable');return r.json();}));
 const nodes=[],hubs=[{id:'buildings',label:'BUILDINGS',x:330,y:420,color:'#b9d49a',file:'assets/rincon-map.json',type:'building'},{id:'census',label:'CENSUS / ACS',x:830,y:275,color:'#edc987',file:'assets/data.json',type:'census'},{id:'water',label:'WATER / COASTLINE',x:815,y:650,color:'#8bcece',file:'assets/rincon-map.json',type:'water'}];
 const buildings=map.filter(f=>f.type==='building');
 buildings.forEach((f,i)=>{const angle=i*2.39996,r=65+Math.sqrt(i/buildings.length)*205;nodes.push({id:'osm-'+f.id,label:f.tags.name||[f.tags['addr:housenumber'],f.tags['addr:street']].filter(Boolean).join(' ')||'OSM building '+f.id,x:330+Math.cos(angle)*r,y:420+Math.sin(angle)*r,type:'building',hub:'buildings',record:f,url:'https://www.openstreetmap.org/way/'+f.id,color:'#b9d49a'});});
 const observations=db.cities.flatMap(c=>c.data.map(d=>({city:c,...d})));observations.forEach((o,i)=>{const {city,...data}=o,a=i/observations.length*Math.PI*2,r=125+(i%2)*26;nodes.push({id:`${city.id}-${o.year}`,label:`${city.name} · ${o.year}`,x:830+Math.cos(a)*r,y:275+Math.sin(a)*r,type:'census',hub:'census',color:'#edc987',record:{cityId:city.id,cityName:city.name,state:city.state,geoid:city.geoid,...data},url:data.sources.b25064});});
 map.filter(f=>f.type==='water').forEach((f,i)=>nodes.push({id:'water-'+f.id,label:f.tags.name||'Water '+f.id,x:815+Math.cos(i*2.4)*95,y:650+Math.sin(i*2.4)*70,type:'water',hub:'water',color:'#8bcece',record:f,url:'https://www.openstreetmap.org/#map=17/37.7891/-122.3908'}));
 for(const h of hubs)h.record={sourceFile:h.file,recordType:h.type,recordCount:nodes.filter(n=>n.type===h.type).length,...(h.type==='census'?{dataset:db.dataset,notes:db.notes,years:db.years}:{source:'OpenStreetMap',geometry:'longitude, latitude coordinate pairs'})};
 const graph=$('#graph'),layer=el('g');graph.append(layer);let filter='all',selection=null,view={x:0,y:0,w:1100,h:800};
 function inspect(n){selection=n.id;selectedJSON=JSON.stringify(n.record,null,2);$('#record-title').textContent=n.label;$('#record-type').textContent=n.type.toUpperCase();$('#record-description').textContent=n.file?'Dataset metadata and record count. Select a connected node to read a complete record.':n.type==='census'?'Exact saved ACS observation. Rent is monthly; income is annual. Geography is the named city, not Rincon Hill.':'Exact saved map feature, including original tags and geometry. No simulated listing prices.';$('#json').textContent=selectedJSON;$('#copy-status').textContent='';$('#source-links').replaceChildren();for(const [label,url]of [['Open source ↗',n.url||n.file],['Download dataset ↓',n.type==='census'?'assets/data.json':'assets/rincon-map.json']]){const a=document.createElement('a');a.textContent=label;a.href=url;if(label.startsWith('Download'))a.download='';else{a.target='_blank';a.rel='noreferrer';}$('#source-links').append(a);}draw();}
 function draw(){layer.replaceChildren();const q=$('#search').value.trim().toLowerCase(),visible=nodes.filter(n=>(filter==='all'||n.type===filter)&&(!q||JSON.stringify(n.record).toLowerCase().includes(q)||n.label.toLowerCase().includes(q)));const activeHubs=hubs.filter(h=>filter==='all'||h.type===filter);
  for(const h of activeHubs)layer.append(el('line',{x1:620,y1:440,x2:h.x,y2:h.y,stroke:h.color,'stroke-opacity':.25,'stroke-dasharray':'4 7'}));
  layer.append(el('text',{x:620,y:427,'text-anchor':'middle',fill:'#ccdbc0','font-size':11,'letter-spacing':2},'DATASCAPE'),el('circle',{cx:620,cy:440,r:4,fill:'#ccdbc0'}));
  for(const n of visible){const h=hubs.find(h=>h.id===n.hub);layer.append(el('line',{x1:h.x,y1:h.y,x2:n.x,y2:n.y,stroke:n.color,'stroke-opacity':selection===n.id?.9:.15,'stroke-width':selection===n.id?2:1}));}
  for(const n of [...visible,...activeHubs]){const hub=Boolean(n.file),g=el('g',{class:'record-node',tabindex:0,role:'button','aria-label':n.label,'data-record-id':n.id,'aria-pressed':String(selection===n.id)});g.append(el('circle',{cx:n.x,cy:n.y,r:hub?30:selection===n.id?9:6,fill:hub?'#29473b':n.color,stroke:selection===n.id?'#fff2b4':n.color,'stroke-width':hub||selection===n.id?2:0}));g.append(el('title',{},n.label));if(hub||n.id===selection||q||n.type!=='building')g.append(el('text',{x:n.x,y:n.y+(hub?47:19),'text-anchor':'middle',fill:n.color,'font-size':hub?12:n.type==='census'?8:10,'paint-order':'stroke',stroke:'#213a32','stroke-width':3},n.label));g.addEventListener('click',()=>inspect(n));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect(n);}});layer.append(g);}
  $('#count').textContent=`${visible.length} / ${nodes.length} source records · ${activeHubs.length} dataset groups`;$('#empty').hidden=visible.length>0;
 }
 $('#search').addEventListener('input',draw);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw();}));
 const applyView=()=>graph.setAttribute('viewBox',`${view.x} ${view.y} ${view.w} ${view.h}`);
 function zoom(factor){const w=Math.max(300,Math.min(1800,view.w*factor)),h=w*800/1100;view={x:view.x+(view.w-w)/2,y:view.y+(view.h-h)/2,w,h};applyView();}
 $('#zoom-in').onclick=()=>zoom(.8);$('#zoom-out').onclick=()=>zoom(1.25);$('#reset').onclick=()=>{view={x:0,y:0,w:1100,h:800};applyView();};graph.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.1:.9);},{passive:false});let drag=null;
 graph.addEventListener('pointerdown',e=>{if(e.target.closest('.record-node'))return;drag={x:e.clientX,y:e.clientY,vx:view.x,vy:view.y};graph.setPointerCapture(e.pointerId);});graph.addEventListener('pointermove',e=>{if(!drag)return;const scale=Math.max(view.w/graph.clientWidth,view.h/graph.clientHeight);view.x=drag.vx-(e.clientX-drag.x)*scale;view.y=drag.vy-(e.clientY-drag.y)*scale;applyView();});graph.addEventListener('pointerup',()=>drag=null);graph.addEventListener('pointercancel',()=>drag=null);
 $('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(selectedJSON);$('#copy-status').textContent='JSON copied.';}catch{$('#copy-status').textContent='Select and copy the JSON below.';}};
 inspect(nodes.find(n=>n.record.tags?.['addr:street']==='Spear Street'&&n.record.tags?.['addr:housenumber']==='338')||nodes[0]);document.body.dataset.ready='true';
}catch(e){$('#error').hidden=false;console.error(e);}
